USE smarttcm;

-- =====================================================
-- 一、中药知识（50味常用中药）
-- =====================================================
INSERT INTO questions (competition, question_type, question_category, content_category, question, answer, answer_only, knowledge_point, primary_project, secondary_project, core_connotation, text_level) VALUES
('中医知识库', '中药', '中药学', '解表药', '麻黄的功效与主治是什么？', '发汗解表、宣肺平喘、利水消肿。主治风寒感冒、胸闷喘咳、风水浮肿。', '麻黄为辛温解表药之首，善于开腠理、透毛窍、发汗解表。其宣肺平喘之功，用于风寒外束、肺气不宣之喘咳；利水消肿之功，用于风水水肿。', '麻黄；辛温解表；发汗解表；宣肺平喘', '中药学', '解表药', '麻黄为发汗解表第一药，性温味辛，归肺、膀胱经，善于宣散肺气、开泄腠理', '入门'),
('中医知识库', '中药', '中药学', '解表药', '桂枝的功效与主治是什么？', '发汗解肌、温通经脉、助阳化气。主治风寒感冒、寒湿痹痛、痰饮蓄水。', '桂枝辛甘温，归心肺膀胱经。既可发散风寒，又可温通经脉，为治疗风寒感冒之要药。与麻黄相须为用，增强发汗之力。', '桂枝；辛温解表；发汗解肌；温通经脉', '中药学', '解表药', '桂枝性辛甘温，既可解表又可温里，是调和营卫的重要药物', '入门'),
('中医知识库', '中药', '中药学', '清热药', '石膏的功效与主治是什么？', '清热泻火、除烦止渴。主治温热病气分实热证、肺热喘咳、胃火牙痛。', '石膏辛甘大寒，归肺胃经。为清解阳明胃经实热之要药。生用清热泻火，煅用收湿敛疮。与知母相须为用，治气分实热。', '石膏；清热泻火；气分实热；白虎汤', '中药学', '清热药', '石膏为清热泻火之重镇药，善清肺胃之热，为白虎汤之君药', '入门'),
('中医知识库', '中药', '中药学', '清热药', '黄芩的功效与主治是什么？', '清热燥湿、泻火解毒、止血安胎。主治湿温暑湿、肺热咳嗽、血热出血、胎动不安。', '黄芩苦寒，归肺胆脾大肠经。善清肺火及上焦之热，又能清热燥湿、泻火解毒。炒炭止血，清热安胎。', '黄芩；清热燥湿；泻火解毒；清热安胎', '中药学', '清热药', '黄芩为清热燥湿之要药，尤善清肺火，主治上焦热证', '入门'),
('中医知识库', '中药', '中药学', '清热药', '黄连的功效与主治是什么？', '清热燥湿、泻火解毒。主治湿热痞满、呕吐吞酸、泻痢、高热神昏、心烦不寐。', '黄连苦寒，归心脾胃肝胆大肠经。为清热燥湿、泻火解毒之要药，尤善清中焦湿热、泻心胃之火。', '黄连；清热燥湿；泻火解毒；中焦湿热', '中药学', '清热药', '黄连为清热燥湿第一要药，大苦大寒，尤善清心胃之火', '入门'),
('中医知识库', '中药', '中药学', '泻下药', '大黄的功效与主治是什么？', '泻下攻积、清热泻火、凉血止血、解毒祛瘀。主治积滞便秘、血热吐衄、目赤咽肿、热毒疮疡。', '大黄苦寒，归脾胃大肠肝心经。为泻下攻积之要药，有"将军"之称。既能泻下通便，又能清热泻火、活血祛瘀。', '大黄；泻下攻积；清热泻火；活血祛瘀', '中药学', '泻下药', '大黄性猛善走，有将军之名，为泻热通便、推陈致新之要药', '入门'),
('中医知识库', '中药', '中药学', '祛风湿药', '独活的功效与主治是什么？', '祛风除湿、通痹止痛。主治风寒湿痹、腰膝酸痛、少阴伏风头痛。', '独活辛苦微温，归肾膀胱经。善祛下焦风寒湿邪，为治风寒湿痹、腰膝酸痛之要药。与羌活相须为用，羌活治上，独活治下。', '独活；祛风除湿；通痹止痛；下焦风湿', '中药学', '祛风湿药', '独活善祛下焦风寒湿邪，为治疗腰膝酸痛之要药', '入门'),
('中医知识库', '中药', '中药学', '化湿药', '苍术的功效与主治是什么？', '燥湿健脾、祛风散寒。主治湿阻中焦、脘腹胀满、风湿痹痛、风寒感冒。', '苍术辛苦温，归脾胃肝经。芳香燥烈，内化湿浊以健脾，外散风寒以祛湿。为治湿阻中焦之要药。', '苍术；燥湿健脾；祛风散寒；湿阻中焦', '中药学', '化湿药', '苍术芳香燥烈，善燥湿健脾，为治疗湿邪困脾之主药', '入门'),
('中医知识库', '中药', '中药学', '利水渗湿药', '茯苓的功效与主治是什么？', '利水渗湿、健脾、宁心。主治水肿尿少、痰饮眩悸、脾虚食少、便溏泄泻、心神不安。', '茯苓甘淡平，归心脾肾经。既能利水渗湿，又可健脾宁心。药性平和，利水而不伤正气，为利水渗湿之要药。', '茯苓；利水渗湿；健脾宁心；四君子汤', '中药学', '利水渗湿药', '茯苓药性平和，既能利水渗湿，又能健脾宁心，为补泻兼施之品', '入门'),
('中医知识库', '中药', '中药学', '温里药', '附子的功效与主治是什么？', '回阳救逆、补火助阳、散寒止痛。主治亡阳证、阳虚证、寒痹证。', '附子辛甘大热，有毒，归心肾脾经。为回阳救逆第一要药。上助心阳以通脉，下补肾阳以益火，能挽救散失之元阳。', '附子；回阳救逆；补火助阳；有毒', '中药学', '温里药', '附子性大热有毒，为回阳救逆第一要药，善补命门之火', '中级'),
('中医知识库', '中药', '中药学', '温里药', '干姜的功效与主治是什么？', '温中散寒、回阳通脉、温肺化饮。主治脘腹冷痛、呕吐泄泻、亡阳证、寒饮喘咳。', '干姜辛热，归脾胃心肺经。为温中散寒之要药，善温脾胃之阳。与附子相须为用，增强回阳救逆之力。', '干姜；温中散寒；回阳通脉；温肺化饮', '中药学', '温里药', '干姜辛热守而不走，善温中散寒，为治疗脾胃寒证之主药', '入门'),
('中医知识库', '中药', '中药学', '理气药', '陈皮的功效与主治是什么？', '理气健脾、燥湿化痰。主治脘腹胀满、食少吐泻、咳嗽痰多。', '陈皮辛苦温，归脾肺经。为理气健脾、燥湿化痰之要药。辛散苦降，温和不峻，为临床最常用之理气药。', '陈皮；理气健脾；燥湿化痰；二陈汤', '中药学', '理气药', '陈皮为理气调中之佳品，以陈久者良，故称陈皮', '入门'),
('中医知识库', '中药', '中药学', '消食药', '山楂的功效与主治是什么？', '消食化积、活血散瘀。主治肉食积滞、胃脘胀满、泻痢腹痛、瘀血经闭。', '山楂酸甘微温，归脾胃肝经。善于消化肉食积滞，为消食化积之要药。又能活血散瘀，治妇人瘀血诸证。', '山楂；消食化积；活血散瘀；消化肉积', '中药学', '消食药', '山楂善消肉食之积，为消食化积之要药，兼能活血化瘀', '入门'),
('中医知识库', '中药', '中药学', '止血药', '三七的功效与主治是什么？', '化瘀止血、活血定痛。主治出血证、跌打损伤、瘀血肿痛。', '三七甘微苦温，归肝胃经。既能止血，又能散瘀，药效卓著，有"止血不留瘀，化瘀不伤正"之特点。为伤科要药。', '三七；化瘀止血；活血定痛；止血不留瘀', '中药学', '止血药', '三七有止血神药之称，止血而不留瘀，化瘀而不伤正', '入门'),
('中医知识库', '中药', '中药学', '活血化瘀药', '丹参的功效与主治是什么？', '活血祛瘀、通经止痛、清心除烦、凉血消痈。主治月经不调、痛经经闭、胸痹心痛、疮疡肿毒。', '丹参苦微寒，归心肝经。为活血化瘀之要药，前人有"一味丹参散，功同四物汤"之说。善治血瘀诸证。', '丹参；活血祛瘀；通经止痛；一味丹参散功同四物汤', '中药学', '活血化瘀药', '丹参为活血化瘀之要药，有"一味丹参功同四物"之说', '入门'),
('中医知识库', '中药', '中药学', '化痰止咳药', '半夏的功效与主治是什么？', '燥湿化痰、降逆止呕、消痞散结。主治湿痰咳嗽、呕吐反胃、胸脘痞闷、梅核气。', '半夏辛温，有毒，归脾胃肺经。为燥湿化痰、降逆止呕之要药。善治脏腑之湿痰，为止呕之良药。', '半夏；燥湿化痰；降逆止呕；有毒；二陈汤', '中药学', '化痰止咳药', '半夏为化痰止呕之要药，尤善治湿痰与胃气上逆之呕吐', '入门'),
('中医知识库', '中药', '中药学', '安神药', '酸枣仁的功效与主治是什么？', '养心益肝、安神、敛汗。主治虚烦不眠、惊悸多梦、体虚多汗。', '酸枣仁甘酸平，归心肝胆经。为养心安神之要药，善治心肝血虚之失眠。与柏子仁相须为用。', '酸枣仁；养心安神；敛汗；失眠', '中药学', '安神药', '酸枣仁为养心安神之要药，善治心肝血虚所致失眠', '入门'),
('中医知识库', '中药', '中药学', '平肝熄风药', '天麻的功效与主治是什么？', '息风止痉、平抑肝阳、祛风通络。主治小儿惊风、癫痫抽搐、头痛眩晕、手足不遂。', '天麻甘平，归肝经。为治风之圣药，既能息风止痉，又能平抑肝阳、祛风通络。善治肝风内动之眩晕。', '天麻；息风止痉；平抑肝阳；治风圣药', '中药学', '平肝熄风药', '天麻为治风要药，尤善治肝风内动之眩晕头痛', '入门'),
('中医知识库', '中药', '中药学', '补气药', '人参的功效与主治是什么？', '大补元气、补脾益肺、生津止渴、安神益智。主治气虚欲脱、脾气不足、肺气亏虚、津伤口渴。', '人参甘微苦微温，归脾肺心经。为补气第一要药，能大补元气、挽救虚脱。补脾益肺之力尤强。', '人参；大补元气；补脾益肺；补气第一要药', '中药学', '补虚药', '人参为补气之长，善大补元气，为拯危救脱之要药', '入门'),
('中医知识库', '中药', '中药学', '补气药', '黄芪的功效与主治是什么？', '补气升阳、益卫固表、利水消肿、托毒生肌。主治气虚乏力、食少便溏、中气下陷、表虚自汗。', '黄芪甘微温，归脾肺经。为补气升阳之要药，善补脾肺之气，又能益卫固表。与人参相比，人参补气于内，黄芪补气于外。', '黄芪；补气升阳；益卫固表；补中益气汤', '中药学', '补虚药', '黄芪善补脾肺之气，升阳举陷，为补气升阳之要药', '入门'),
('中医知识库', '中药', '中药学', '补气药', '白术的功效与主治是什么？', '健脾益气、燥湿利水、止汗安胎。主治脾虚食少、腹胀泄泻、痰饮眩悸、水肿、胎动不安。', '白术苦甘温，归脾胃经。为健脾益气之要药，善补脾胃、燥湿浊。与苍术相比，白术重在健脾，苍术重在燥湿。', '白术；健脾益气；燥湿利水；四君子汤', '中药学', '补虚药', '白术为健脾第一要药，善健脾益气、燥湿利水', '入门'),
('中医知识库', '中药', '中药学', '补血药', '当归的功效与主治是什么？', '补血活血、调经止痛、润肠通便。主治血虚萎黄、月经不调、经闭痛经、虚寒腹痛、肠燥便秘。', '当归甘辛温，归肝心脾经。为补血调经之要药，既能补血，又能活血，补中有动，行中有补。前人称其为"妇科圣药"。', '当归；补血活血；调经止痛；妇科圣药', '中药学', '补虚药', '当归为补血调经之要药，补血活血兼能止痛，有"妇科圣药"之称', '入门'),
('中医知识库', '中药', '中药学', '补血药', '熟地黄的功效与主治是什么？', '补血滋阴、益精填髓。主治血虚萎黄、心悸怔忡、月经不调、肝肾阴虚、腰膝酸软。', '熟地黄甘微温，归肝肾经。为补血滋阴之要药，善补肝肾之阴血。与生地黄相比，生地偏于清热凉血，熟地偏于补血滋阴。', '熟地黄；补血滋阴；益精填髓；四物汤', '中药学', '补虚药', '熟地黄为补血滋阴之要药，善补肝肾精血', '入门'),
('中医知识库', '中药', '中药学', '补阴药', '枸杞子的功效与主治是什么？', '滋补肝肾、益精明目。主治肝肾阴虚、精血不足、腰膝酸痛、眩晕耳鸣、内热消渴、目昏不明。', '枸杞子甘平，归肝肾经。为滋补肝肾之要药，既能补阴，又能补阳，平补肝肾，为常用的养生保健中药。', '枸杞子；滋补肝肾；益精明目；平补肝肾', '中药学', '补虚药', '枸杞子药性平和，为滋补肝肾、益精明目之佳品', '入门'),
('中医知识库', '中药', '中药学', '补阳药', '鹿茸的功效与主治是什么？', '补肾阳、益精血、强筋骨。主治肾阳不足、精血亏虚、阳痿滑精、宫冷不孕、骨软行迟。', '鹿茸甘咸温，归肾肝经。为补肾阳、益精血之要药，补力峻猛。善补肾阳、益精血、强筋骨、调冲任。', '鹿茸；补肾阳；益精血；峻补要药', '中药学', '补虚药', '鹿茸为峻补肾阳之要药，善补肾阳益精血，药力峻猛', '中级'),
('中医知识库', '中药', '中药学', '收涩药', '五味子的功效与主治是什么？', '收敛固涩、益气生津、补肾宁心。主治久咳虚喘、自汗盗汗、遗精滑精、久泻不止、津伤口渴。', '五味子酸甘温，归肺心肾经。五味俱全，以酸收为主。上敛肺气而止咳，下滋肾阴而涩精，内益气生津，外敛汗止泻。', '五味子；收敛固涩；益气生津；补肾宁心', '中药学', '收涩药', '五味子酸收甘补，性温而不燥，为收敛固涩之要药', '入门'),
('中医知识库', '中药', '中药学', '解表药', '薄荷的功效与主治是什么？', '疏散风热、清利头目、利咽透疹、疏肝行气。主治风热感冒、头痛目赤、咽喉肿痛、麻疹不透。', '薄荷辛凉，归肺肝经。为疏散风热之常用药物，芳香辟秽，清利头目。善于疏风散热、清利咽喉。', '薄荷；疏散风热；清利头目；辛凉解表', '中药学', '解表药', '薄荷辛凉芳香，善疏散风热、清利头目', '入门'),
('中医知识库', '中药', '中药学', '清热药', '金银花的功效与主治是什么？', '清热解毒、疏散风热。主治外感风热、温病初起、热毒疮痈、咽喉肿痛。', '金银花甘寒，归肺心胃经。为清热解毒之要药，善散肺经邪热、清心胃热毒。为治疗热毒疮痈之要药。', '金银花；清热解毒；疏散风热；银翘散', '中药学', '清热药', '金银花为清热解毒之要药，善治外感风热与热毒疮痈', '入门'),
('中医知识库', '中药', '中药学', '清热药', '板蓝根的功效与主治是什么？', '清热解毒、凉血利咽。主治温毒发斑、舌绛紫暗、烂喉丹痧、咽喉肿痛、大头瘟疫。', '板蓝根苦寒，归心胃经。善于清热解毒、凉血利咽，为治疗温热病之要药。对咽喉肿痛、温毒发斑有特效。', '板蓝根；清热解毒；凉血利咽；温热病', '中药学', '清热药', '板蓝根善清热解毒凉血，为防治温热病之常用药', '入门'),
('中医知识库', '中药', '中药学', '补阴药', '麦冬的功效与主治是什么？', '养阴润肺、益胃生津、清心除烦。主治肺燥干咳、阴虚劳嗽、胃阴不足、津伤口渴、心烦失眠。', '麦冬甘微苦微寒，归心肺胃经。为养阴润肺之要药，善养肺胃之阴、清心除烦。', '麦冬；养阴润肺；益胃生津；清心除烦', '中药学', '补虚药', '麦冬善养肺胃之阴、清心除烦，为养阴生津之要药', '入门'),
('中医知识库', '中药', '中药学', '理气药', '川芎的功效与主治是什么？', '活血行气、祛风止痛。主治血瘀气滞之痛证、头痛、风湿痹痛。为"血中之气药"。', '川芎辛温，归肝胆心包经。为活血行气之要药，既能活血，又能行气，为"血中气药"。善治头痛，为治头痛之要药。', '川芎；活血行气；祛风止痛；血中气药', '中药学', '理气药', '川芎为血中之气药，善活血行气、祛风止痛，尤善治头痛', '入门'),
('中医知识库', '中药', '中药学', '平肝熄风药', '钩藤的功效与主治是什么？', '清热平肝、息风止痉。主治肝火上攻之头痛眩晕、肝风内动之惊痫抽搐。', '钩藤甘凉，归肝心包经。为清热平肝、息风止痉之要药。善清肝热、息肝风。不宜久煎。', '钩藤；清热平肝；息风止痉；不宜久煎', '中药学', '平肝熄风药', '钩藤善清热平肝、息风止痉，为治疗肝风内动之常用药', '入门'),

-- =====================================================
-- 二、经典方剂知识（20个常用方剂）
-- =====================================================
('中医知识库', '方剂', '方剂学', '补益剂', '四君子汤的组成、功效与主治是什么？', '由人参、白术、茯苓、甘草四味药组成。功效：益气健脾。主治脾胃气虚证，症见面色萎白、语声低微、气短乏力、食少便溏。', '四君子汤为补气的基础方，后世众多补气方剂均由此方衍化而来，如六君子汤、参苓白术散等。方中人参补气，白术健脾，茯苓渗湿，甘草和中，四药协同，共奏益气健脾之功。', '四君子汤；益气健脾；补气基础方', '方剂学', '补益剂', '四君子汤为补气诸方之祖，益气健脾、调和脾胃', '中级'),
('中医知识库', '方剂', '方剂学', '补血剂', '四物汤的组成、功效与主治是什么？', '由熟地黄、当归、白芍、川芎四味药组成。功效：补血调血。主治营血虚滞证，症见面色萎黄、头晕目眩、心悸失眠、妇女月经不调。', '四物汤为补血调经的基础方。方中熟地滋阴补血，当归补血活血，白芍养血和营，川芎活血行气。四药配合，补中有活，动静结合。', '四物汤；补血调血；补血基础方', '方剂学', '补血剂', '四物汤为补血调经之基础方，补血而不滞血，行血而不伤血', '中级'),
('中医知识库', '方剂', '方剂学', '解表剂', '麻黄汤的组成、功效与主治是什么？', '由麻黄、桂枝、杏仁、甘草四味药组成。功效：发汗解表、宣肺平喘。主治外感风寒表实证，症见恶寒发热、无汗而喘、头痛身疼。', '麻黄汤为辛温解表之峻剂。方中麻黄发汗解表、宣肺平喘为君药；桂枝温经散寒为臣药，助麻黄发汗；杏仁降肺气为佐药，助麻黄平喘；甘草调和诸药为使药。', '麻黄汤；发汗解表；宣肺平喘；风寒表实证', '方剂学', '解表剂', '麻黄汤为辛温解表之代表方，主治外感风寒表实证', '中级'),
('中医知识库', '方剂', '方剂学', '和解剂', '小柴胡汤的组成、功效与主治是什么？', '由柴胡、黄芩、人参、半夏、甘草、生姜、大枣组成。功效：和解少阳。主治少阳证，症见往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕。', '小柴胡汤为和解少阳之代表方。方中柴胡疏解少阳之邪为君药，黄芩清泄少阳之热为臣药，二药合用，和解少阳。人参、半夏、甘草、生姜、大枣益气和胃、扶正祛邪。', '小柴胡汤；和解少阳；往来寒热；少阳证', '方剂学', '和解剂', '小柴胡汤为和解少阳之主方，主治少阳病证', '中级'),
('中医知识库', '方剂', '方剂学', '清热剂', '白虎汤的组成、功效与主治是什么？', '由石膏、知母、粳米、甘草组成。功效：清热生津。主治气分热盛证，症见壮热面赤、烦渴引饮、大汗出、脉洪大有力。', '白虎汤为清气分热之代表方。方中石膏清热泻火为君药，知母清热滋阴为臣药，粳米、甘草益胃生津为佐使。四药合用，清热生津。', '白虎汤；清热生津；气分热盛；四大症状', '方剂学', '清热剂', '白虎汤为清气分热之代表方，主治气分实热之"四大"证', '中级'),
('中医知识库', '方剂', '方剂学', '补益剂', '六味地黄丸的组成、功效与主治是什么？', '由熟地黄、山茱萸、山药、泽泻、茯苓、牡丹皮组成。功效：滋阴补肾。主治肾阴虚证，症见头晕耳鸣、腰膝酸软、骨蒸潮热、盗汗遗精。', '六味地黄丸为滋阴补肾的代表方。方中熟地、山茱萸、山药"三补"补肾肝脾之阴，泽泻、茯苓、丹皮"三泻"泻肾肝脾之浊。补中有泻，以补为主。', '六味地黄丸；滋阴补肾；三补三泻', '方剂学', '补益剂', '六味地黄丸为滋阴补肾之代表方，补中有泻，以补为主', '中级'),
('中医知识库', '方剂', '方剂学', '理气剂', '逍遥散的组成、功效与主治是什么？', '由柴胡、当归、白芍、白术、茯苓、甘草、薄荷、生姜组成。功效：疏肝解郁、养血健脾。主治肝郁血虚脾弱证，症见两胁作痛、头痛目眩、口燥咽干、神疲食少、月经不调。', '逍遥散为调和肝脾的代表方。方中柴胡疏肝解郁为君药，当归、白芍养血柔肝为臣药，白术、茯苓健脾祛湿为佐药，薄荷散肝郁、生姜温胃为使药。', '逍遥散；疏肝解郁；养血健脾；调和肝脾', '方剂学', '理气剂', '逍遥散为疏肝解郁、调和肝脾之代表方', '中级'),
('中医知识库', '方剂', '方剂学', '温里剂', '理中丸的组成、功效与主治是什么？', '由人参、干姜、白术、甘草组成。功效：温中祛寒、补气健脾。主治脾胃虚寒证，症见脘腹疼痛、喜温喜按、呕吐便溏、畏寒肢冷。', '理中丸为温中祛寒之代表方。方中干姜温中祛寒为君药，人参补气健脾为臣药，白术健脾燥湿为佐药，甘草调和诸药为使药。', '理中丸；温中祛寒；补气健脾；脾胃虚寒', '方剂学', '温里剂', '理中丸为温中祛寒之代表方，主治中焦虚寒', '中级'),
('中医知识库', '方剂', '方剂学', '治风剂', '川芎茶调散的组成、功效与主治是什么？', '由川芎、荆芥、白芷、羌活、甘草、细辛、防风、薄荷组成。功效：疏风止痛。主治外感风邪之头痛，症见偏正头痛、巅顶作痛。', '川芎茶调散为治疗外感风邪头痛之代表方。方中川芎善治少阳头痛为君药，薄荷、荆芥疏风散邪为臣药，诸药合用，疏散风邪、止痛。', '川芎茶调散；疏风止痛；外感头痛', '方剂学', '治风剂', '川芎茶调散为治疗外感风邪头痛之代表方', '中级'),
('中医知识库', '方剂', '方剂学', '祛湿剂', '藿香正气散的组成、功效与主治是什么？', '由藿香、紫苏、白芷、大腹皮、茯苓、白术、陈皮、半夏、厚朴、桔梗、甘草组成。功效：解表化湿、理气和中。主治外感风寒、内伤湿滞证，症见恶寒发热、头痛、胸膈满闷、脘腹疼痛、呕吐泄泻。', '藿香正气散为治疗外感风寒、内伤湿滞之代表方。方中藿香芳香化湿、和胃止呕为君药，诸药合用，表里双解、升清降浊。', '藿香正气散；解表化湿；理气和中；暑湿感冒', '方剂学', '祛湿剂', '藿香正气散为治疗外感风寒、内伤湿滞之常用方', '中级'),
('中医知识库', '方剂', '方剂学', '补益剂', '补中益气汤的组成、功效与主治是什么？', '由黄芪、人参、白术、甘草、当归、陈皮、升麻、柴胡组成。功效：补中益气、升阳举陷。主治脾胃气虚证、气虚下陷证、气虚发热证。', '补中益气汤为补气升阳之代表方。方中黄芪补气升阳为君药，人参、白术、甘草补气健脾为臣药，当归养血、陈皮理气、升麻柴胡升阳举陷为佐使。', '补中益气汤；补中益气；升阳举陷；甘温除热', '方剂学', '补益剂', '补中益气汤为补气升阳之代表方，创"甘温除热"之法', '中级'),
('中医知识库', '方剂', '方剂学', '安神剂', '酸枣仁汤的组成、功效与主治是什么？', '由酸枣仁、茯苓、知母、川芎、甘草组成。功效：养血安神、清热除烦。主治虚烦不眠证，症见心悸失眠、虚烦不安、头目眩晕。', '酸枣仁汤为养血安神之代表方。方中酸枣仁养心安神为君药，茯苓宁心安神为臣药，知母清热除烦、川芎调畅气血为佐药。', '酸枣仁汤；养血安神；清热除烦；虚烦不眠', '方剂学', '安神剂', '酸枣仁汤为养血安神之代表方，善治肝血不足之虚烦不眠', '中级'),

-- =====================================================
-- 三、常用穴位知识（20个重要穴位）
-- =====================================================
('中医知识库', '穴位', '针灸学', '手太阴肺经', '列缺穴的定位与主治是什么？', '定位：在前臂桡侧缘，桡骨茎突上方，腕横纹上1.5寸。主治：咳嗽、气喘、咽喉肿痛、头痛、项强、口眼歪斜。', '列缺为手太阴肺经之络穴，通任脉，为八脉交会穴之一。善于疏风解表、宣肺利气，治疗外感咳嗽、头痛项强等。', '列缺；手太阴肺经；络穴；八脉交会穴', '针灸学', '手太阴肺经', '列缺为肺经络穴，通任脉，善治外感咳嗽、头痛项强', '入门'),
('中医知识库', '穴位', '针灸学', '手阳明大肠经', '合谷穴的定位与主治是什么？', '定位：在手背第1、2掌骨间，第2掌骨桡侧中点。主治：头痛、牙痛、面瘫、发热、无汗、多汗、痛经、滞产。为"四总穴"之一。', '合谷为手阳明大肠经原穴，别名"虎口"。为临床最常用穴位之一，有"面口合谷收"之说，善治头面诸疾。孕妇禁针。', '合谷；手阳明大肠经；原穴；四总穴；面口合谷收', '针灸学', '手阳明大肠经', '合谷为大肠经原穴，善治头面口齿诸疾，有"面口合谷收"之说', '入门'),
('中医知识库', '穴位', '针灸学', '足阳明胃经', '足三里穴的定位与主治是什么？', '定位：在小腿前外侧，犊鼻下3寸，距胫骨前缘1横指。主治：胃痛、呕吐、腹胀、泄泻、便秘、虚劳、保健强壮。为"四总穴"之一。', '足三里为足阳明胃经合穴，为强壮保健要穴，有"肚腹三里留"之说。善补脾胃、益气血、扶正培元。经常按摩足三里可增强体质。', '足三里；足阳明胃经；合穴；四总穴；保健要穴；肚腹三里留', '针灸学', '足阳明胃经', '足三里为保健强壮第一穴，善补脾胃、益气血、扶正培元', '入门'),
('中医知识库', '穴位', '针灸学', '足太阴脾经', '三阴交穴的定位与主治是什么？', '定位：在小腿内侧，内踝尖上3寸，胫骨内侧缘后方。主治：月经不调、痛经、崩漏、带下、遗精、阳痿、失眠、腹胀、泄泻。', '三阴交为足太阴脾经穴，为肝脾肾三阴经交会穴。善治妇科、前阴病及脾胃病，为妇科要穴。孕妇禁针。', '三阴交；足太阴脾经；三阴经交会；妇科要穴', '针灸学', '足太阴脾经', '三阴交为肝脾肾三阴经交会穴，善治妇科诸疾', '入门'),
('中医知识库', '穴位', '针灸学', '手少阴心经', '神门穴的定位与主治是什么？', '定位：在腕部，腕掌侧横纹尺侧端，尺侧腕屈肌腱桡侧凹陷处。主治：失眠、心悸、怔忡、健忘、癫狂痫、胸痹。', '神门为手少阴心经原穴，为治疗心神病证之要穴。善于宁心安神，治疗失眠、心悸等心神不宁之证。', '神门；手少阴心经；原穴；安神要穴', '针灸学', '手少阴心经', '神门为心经原穴，善于宁心安神，为治疗失眠之要穴', '入门'),
('中医知识库', '穴位', '针灸学', '督脉', '百会穴的定位与主治是什么？', '定位：在头部，前发际正中直上5寸，两耳尖连线中点。主治：头痛、眩晕、中风昏迷、癫狂痫、脱肛、子宫脱垂。', '百会为督脉穴，位于头顶正中，为百脉之会。善于升阳举陷、醒脑开窍、熄风宁神。为治疗神志病、脱垂证之要穴。', '百会；督脉；百脉之会；升阳举陷；醒脑开窍', '针灸学', '督脉', '百会位于头顶，为百脉聚会之处，善升阳举陷、醒脑开窍', '入门'),
('中医知识库', '穴位', '针灸学', '任脉', '关元穴的定位与主治是什么？', '定位：在下腹部，前正中线上，脐中下3寸。主治：遗精、阳痿、早泄、痛经、月经不调、虚劳、中风脱证。', '关元为任脉穴，为小肠募穴，又是足三阴经与任脉之会。善于培补元气、温肾壮阳，为保健强壮之要穴。艾灸关元可增强体质。', '关元；任脉；小肠募穴；培补元气；保健要穴', '针灸学', '任脉', '关元为培补元气之要穴，善温肾壮阳、保健强身', '入门'),
('中医知识库', '穴位', '针灸学', '督脉', '大椎穴的定位与主治是什么？', '定位：在后正中线上，第7颈椎棘突下凹陷中。主治：热病、疟疾、感冒、咳嗽、气喘、骨蒸潮热、癫痫。', '大椎为督脉穴，为诸阳之会。善于解表清热、截疟止痉，为治疗外感发热之要穴。常用于退热、防治感冒。', '大椎；督脉；诸阳之会；解表清热；退热要穴', '针灸学', '督脉', '大椎为诸阳之会，善解表清热，为退热之要穴', '入门'),
('中医知识库', '穴位', '针灸学', '足太阳膀胱经', '肾俞穴的定位与主治是什么？', '定位：在腰部，第2腰椎棘突下，旁开1.5寸。主治：腰痛、耳鸣、耳聋、遗精、阳痿、月经不调、水肿。', '肾俞为足太阳膀胱经穴，为肾之背俞穴。善于补肾益气、温阳利水，为治疗肾虚证之要穴。常用于治疗腰痛、生殖系统疾病。', '肾俞；足太阳膀胱经；背俞穴；补肾要穴', '针灸学', '足太阳膀胱经', '肾俞为肾之背俞穴，善补肾益气，为治疗肾虚证之要穴', '入门'),
('中医知识库', '穴位', '针灸学', '足厥阴肝经', '太冲穴的定位与主治是什么？', '定位：在足背，第1、2跖骨结合部前方凹陷处。主治：头痛、眩晕、目赤肿痛、胁痛、月经不调、疝气、癫狂痫。', '太冲为足厥阴肝经原穴，善于平肝熄风、疏肝理气。为治疗肝郁气滞、肝阳上亢之要穴。配合谷称为"四关穴"。', '太冲；足厥阴肝经；原穴；平肝熄风；疏肝理气', '针灸学', '足厥阴肝经', '太冲为肝经原穴，善平肝熄风、疏肝理气，为治肝之要穴', '入门'),

-- =====================================================
-- 四、中医基础理论（20个核心概念）
-- =====================================================
('中医知识库', '理论', '中医基础理论', '阴阳学说', '中医阴阳学说的基本内容是什么？', '阴阳学说是中医理论体系的基础。阴阳是对自然界相互关联的某些事物和现象对立双方的概括。基本内容包括：阴阳对立制约、阴阳互根互用、阴阳消长平衡、阴阳相互转化。', '阴阳学说贯穿于中医理论体系的各个方面。人体的组织结构、生理功能、病理变化均可用阴阳来概括。诊断时辨别阴阳是总纲，治疗时调整阴阳是根本。', '阴阳学说；对立制约；互根互用；消长平衡；相互转化', '中医基础理论', '阴阳学说', '阴阳学说为中医理论之基石，贯穿于生理、病理、诊断、治疗各个方面', '入门'),
('中医知识库', '理论', '中医基础理论', '五行学说', '中医五行学说的基本内容是什么？', '五行学说是以木、火、土、金、水五种物质的特性及其运动规律来认识世界的理论。基本内容包括：五行相生（木生火、火生土、土生金、金生水、水生木）、五行相克（木克土、土克水、水克火、火克金、金克木）。', '五行学说用于解释人体脏腑之间的生理功能和病理影响。相生说明脏腑之间的相互资生关系，相克说明脏腑之间的相互制约关系。', '五行学说；相生；相克；木火土金水；脏腑关系', '中医基础理论', '五行学说', '五行学说以木火土金水之特性，阐释脏腑间生克制化关系', '入门'),
('中医知识库', '理论', '中医基础理论', '藏象学说', '中医五脏的主要功能是什么？', '心：心主血脉、心藏神；肺：肺主气、司呼吸、主宣发肃降；脾：脾主运化、脾主统血；肝：肝主疏泄、肝藏血；肾：肾藏精、肾主水、肾主纳气。', '五脏是人体生命活动的核心。心为"君主之官"，肺为"相傅之官"，脾为"仓廪之官"，肝为"将军之官"，肾为"作强之官"。各脏腑分工协作，共同维持人体正常生理功能。', '五脏；心肝脾肺肾；藏象学说；脏腑功能', '中医基础理论', '藏象学说', '五脏为人体生命活动之核心，各有专司又相互协调', '入门'),
('中医知识库', '理论', '中医基础理论', '气血津液', '中医如何认识气、血、津液？', '气是构成人体和维持人体生命活动的最基本物质。血是循行于脉中的富有营养的红色液态物质。津液是机体一切正常水液的总称。气血津液是构成人体和维持生命活动的基本物质。', '气具有推动、温煦、防御、固摄、气化等功能。血具有营养和滋润作用。气为血之帅，血为气之母。津液有滋润和濡养作用。三者相互依存、相互转化。', '气血津液；气为血帅；血为气母；基本物质', '中医基础理论', '气血津液', '气血津液为构成人体和维持生命活动之基本物质', '入门'),
('中医知识库', '理论', '中医基础理论', '经络学说', '中医十二正经的名称和循行规律是什么？', '十二正经包括：手三阴经（手太阴肺经、手厥阴心包经、手少阴心经）、手三阳经（手阳明大肠经、手少阳三焦经、手太阳小肠经）、足三阴经（足太阴脾经、足厥阴肝经、足少阴肾经）、足三阳经（足阳明胃经、足少阳胆经、足太阳膀胱经）。', '十二正经的循行规律：手三阴经从胸走手，手三阳经从手走头，足三阳经从头走足，足三阴经从足走腹胸。相互之间有表里关系，构成气血循环的系统。', '十二正经；手三阴手三阳足三阴足三阳；经络循行；表里关系', '中医基础理论', '经络学说', '十二正经是经络系统之主体，有规律地联系脏腑、沟通内外', '中级'),
('中医知识库', '理论', '中医基础理论', '病因学说', '中医的"六淫"指什么？', '六淫是指风、寒、暑、湿、燥、火六种外感病邪的统称。当气候变化异常或人体正气不足时，六气变为六淫，侵犯人体而致病。', '六淫致病特点：风为百病之长，善行数变；寒为阴邪，凝滞收引；暑为阳邪，其性炎热；湿为阴邪，重浊黏滞；燥性干涩，易伤津液；火为阳邪，其性炎上。', '六淫；风寒暑湿燥火；外感病邪；致病特点', '中医基础理论', '病因学说', '六淫为外感病邪之总称，各有其致病特点', '入门'),
('中医知识库', '理论', '中医基础理论', '病机学说', '中医"正邪相争"的基本病机是什么？', '正邪相争是中医认识疾病的基本观点。正气是指人体的生理功能和抗病能力，邪气是指各种致病因素。疾病的发生、发展与变化取决于正邪双方的盛衰变化。', '正邪相争决定了疾病的发生和转归。"正气存内，邪不可干"——正气充足则不易发病；"邪之所凑，其气必虚"——正气不足则邪气侵袭而发病。', '正邪相争；正气存内邪不可干；发病原理', '中医基础理论', '病机学说', '正邪相争为中医认识疾病之根本，正气充足则邪不可干', '入门'),
('中医知识库', '理论', '中医基础理论', '四诊', '中医四诊"望闻问切"分别指什么？', '望诊：观察病人的神色形态；闻诊：听声音、嗅气味；问诊：询问病情和相关情况；切诊：切脉和按诊。四诊合参，综合判断病情。', '望诊居四诊之首，"望而知之谓之神"。闻诊通过听声音和嗅气味判断病情。问诊是获取病情资料的主要方法，张景岳有"十问歌"。切诊以脉诊为主，通过寸口脉象判断脏腑气血盛衰。', '四诊；望闻问切；四诊合参；辨证基础', '中医基础理论', '诊法', '望闻问切为中医四大诊法，四诊合参为辨证论治之基础', '入门'),
('中医知识库', '理论', '中医基础理论', '八纲辨证', '中医"八纲辨证"包括哪些内容？', '八纲辨证是中医辨证的基本方法，包括阴阳、表里、寒热、虚实八个纲领。表里辨病位，寒热辨病性，虚实辨邪正盛衰，阴阳为总纲。', '八纲辨证是各种辨证方法的基础。表证属阳，里证可阴可阳；热证属阳，寒证属阴；实证属阳，虚证属阴。临床辨证时需八纲互参，全面分析。', '八纲辨证；阴阳表里寒热虚实；辨证总纲', '中医基础理论', '辨证方法', '八纲辨证为中医辨证之总纲，可概括一切疾病的证候', '入门'),
('中医知识库', '理论', '中医基础理论', '治则治法', '中医"治病求本"的含义是什么？', '治病求本是中医治疗的基本原则，即在治疗疾病时，必须寻求疾病的本质，针对其根本原因进行治疗。"本"指的是疾病的本质，即病因病机。', '治病求本包括正治反治、标本缓急。正治是逆其证候性质而治（寒者热之、热者寒之），反治是顺从疾病假象而治（热因热用、寒因寒用）。急则治其标，缓则治其本。', '治病求本；正治反治；标本缓急；治疗原则', '中医基础理论', '治则治法', '治病求本为中医治疗之最高原则，要求透过现象抓住本质', '中级'),
('中医知识库', '理论', '中医基础理论', '体质学说', '中医九种体质分别是什么？', '平和质、气虚质、阳虚质、阴虚质、痰湿质、湿热质、血瘀质、气郁质、特禀质。九种体质各有特征，平和质为正常体质，其余八种为偏颇体质。', '体质学说源于《黄帝内经》，由王琦教授系统化为九种体质分类。体质不同，对疾病的易感性不同，治疗方法也应因人制宜。辨识体质是中医养生保健的基础。', '九种体质；平和质；气虚质；阳虚质；阴虚质；痰湿质；湿热质；血瘀质；气郁质；特禀质', '中医基础理论', '体质学说', '九种体质各具特征，辨识体质为养生保健之基础', '入门'),

-- =====================================================
-- 五、经络知识（10条主要经络）
-- =====================================================
('中医知识库', '经络', '经络学说', '手太阴肺经', '手太阴肺经的循行路线和主治是什么？', '起于中焦，下络大肠，还循胃口，上膈属肺，沿喉咙，横出腋下，沿上臂内侧前缘下行，过肘，入寸口，上鱼际，出大指端。主治：咳嗽、气喘、胸闷、咽喉肿痛等肺系疾患。', '手太阴肺经共11穴，主要分布在上肢内侧前缘。肺经与大肠经相表里，肺主气、司呼吸，主治呼吸系统疾病。常用穴位有中府、尺泽、列缺、少商等。', '手太阴肺经；十一穴；肺系疾患；循行路线', '经络学说', '手太阴肺经', '手太阴肺经主治肺系疾患，为呼吸系统疾病之主要治疗经脉', '中级'),
('中医知识库', '经络', '经络学说', '足阳明胃经', '足阳明胃经的循行路线和主治是什么？', '起于鼻翼旁，上行至额角，下行沿面部至下颌，分支循喉咙，入缺盆，下膈属胃络脾，直行者经腹部，下行至大腿前外侧，过膝，沿胫骨外侧至足背，止于第二趾端。主治：胃痛、呕吐、腹胀、面瘫、牙痛、下肢痿痹。', '足阳明胃经共45穴，为十二经脉中穴位最多的经脉。从头走足，分布广泛。主治消化系统疾病及头面、下肢疾患。常用穴位有地仓、颊车、梁丘、足三里、丰隆等。', '足阳明胃经；四十五穴；消化系统；循行路线', '经络学说', '足阳明胃经', '足阳明胃经为穴位最多的经脉，主治消化系统疾病', '中级'),
('中医知识库', '经络', '经络学说', '督脉', '督脉的循行路线和主治是什么？', '起于胞中，沿脊柱内上行至风府穴入脑，上行至巅顶百会，经前额下行至鼻柱。为"阳脉之海"，总督一身之阳经。主治：腰脊强痛、头痛、眩晕、癫狂痫、中风昏迷、妇科病。', '督脉共28穴，循行于背部正中线。为阳脉之海，统领全身阳气。主治神志病、热病、腰骶、背、头项局部病证。常用穴位有长强、命门、大椎、百会、水沟等。', '督脉；阳脉之海；二十八穴；神志病', '经络学说', '督脉', '督脉为阳脉之海，总督一身阳气，善治神志病和腰脊疾患', '中级'),
('中医知识库', '经络', '经络学说', '任脉', '任脉的循行路线和主治是什么？', '起于胞中，沿腹部正中线上行，经咽喉，环绕口唇，上至眼眶下。为"阴脉之海"，总任一身之阴经。主治：月经不调、带下、遗精、阳痿、疝气、腹痛、泄泻。', '任脉共24穴，循行于腹部正中线。为阴脉之海，统领全身阴气，又有"任主胞胎"之说。主治泌尿生殖系统疾病和消化系统疾病。常用穴位有中极、关元、气海、神阙、中脘、膻中等。', '任脉；阴脉之海；二十四穴；任主胞胎', '经络学说', '任脉', '任脉为阴脉之海，总任一身阴经，善治泌尿生殖系统疾病', '中级');

